from solution import specialFilter
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


ODD = {'1', '3', '5', '7', '9'}


def reference(nums):
    count = 0
    for n in nums:
        if n > 10:
            s = str(n)
            # n > 10 implies s[0] is a digit (no sign), s[-1] is a digit
            if s[0] in ODD and s[-1] in ODD:
                count += 1
    return count


# --- explicit spec examples ---

def test_spec_example_1():
    assert specialFilter([15, -73, 14, -15]) == 1


def test_spec_example_2():
    assert specialFilter([33, -2, -3, 45, 21, 109]) == 2


# --- boundary around "greater than 10" ---

def test_boundary_10_does_not_count():
    # 10 is not > 10
    assert specialFilter([10]) == 0


def test_boundary_11_counts_when_digits_odd():
    # 11 > 10 and first=1 odd, last=1 odd => must count
    assert specialFilter([11]) == 1


def test_boundary_11_is_only_difference():
    assert specialFilter([11, 10, 12, 9, 10]) == 1


def test_boundary_mixed_just_above_threshold():
    # 13,15,17,19 all >10 with odd-odd; 10,12,14 do not qualify
    assert specialFilter([10, 11, 12, 13, 14, 15]) == 3


def test_first_digit_even_excluded():
    # 21, 45, 41, 69: last odd but first even => 0
    assert specialFilter([21, 45, 41, 69, 25, 27, 29]) == 0


def test_last_digit_even_excluded():
    # first odd but last even => 0
    assert specialFilter([14, 16, 18, 30, 32, 34, 110, 112]) == 0


def test_both_digits_odd_counted():
    assert specialFilter([11, 13, 15, 17, 19, 31, 33, 35, 51, 73, 99, 109, 111]) == 13


def test_empty_list():
    assert specialFilter([]) == 0


def test_all_not_greater_than_10():
    assert specialFilter([-100, -73, -15, -2, 0, 5, 9, 10]) == 0


def test_negative_odd_digit_numbers_do_not_count():
    # negatives are never > 10 even if digits are odd
    assert specialFilter([-11, -13, -33, -15, -73, -111]) == 0


# --- property-based tests ---

@given(st.lists(st.integers(min_value=-300, max_value=500), max_size=20))
def test_property_matches_reference_model(nums):
    assert specialFilter(nums) == reference(nums)


@given(st.lists(st.integers(min_value=11, max_value=200), max_size=20))
def test_property_count_equals_odd_first_and_last(nums):
    expected = sum(
        1 for n in nums if n > 10 and str(n)[0] in ODD and str(n)[-1] in ODD
    )
    assert specialFilter(nums) == expected


@given(st.lists(st.integers(min_value=-500, max_value=10), max_size=20))
def test_property_nothing_at_or_below_10_counts(nums):
    assert specialFilter(nums) == 0


@given(st.lists(st.integers(min_value=-300, max_value=500), max_size=15))
def test_property_order_does_not_matter(nums):
    # counting is order-invariant: reversed list gives same result
    assert specialFilter(list(reversed(nums))) == specialFilter(nums)


@given(st.lists(st.integers(min_value=-300, max_value=500), max_size=15))
def test_property_adding_non_qualifying_does_not_change_count(nums):
    base = specialFilter(nums)
    # 10, 12, 14, 20, 22, negatives, small numbers never qualify
    extra = [10, 12, 14, 20, 22, 40, -11, -33, 0, 8]
    assert specialFilter(nums + extra) == base


@given(st.integers(min_value=0, max_value=9), st.integers(min_value=0, max_value=9))
def test_property_two_digit_construction(d1, d2):
    # construct two-digit number > 10 explicitly; expected from digit parity
    n = 10 * d1 + d2
    assume(n > 10)
    expected = 1 if (str(d1) in ODD and str(d2) in ODD) else 0
    assert specialFilter([n]) == expected
